import unittest
from candidate import will_it_fly

class TestWillItFly(unittest.TestCase):
    def test_flightable_unbalanced_list(self):
        self.assertFalse(will_it_fly([1, 2], 5))

    def test_unflightable_heavy_balanced_list(self):
        self.assertFalse(will_it_fly([3, 2, 3], 1))

    def test_flightable_balanced_heavy_list(self):
        self.assertTrue(will_it_fly([3, 2, 3], 9))

    def test_flightable_single_element_list(self):
        self.assertTrue(will_it_fly([3], 5))

    def test_unflightable_single_element_heavy_list(self):
        self.assertFalse(will_it_fly([3], 3))

    def test_unflightable_empty_list(self):
        self.assertTrue(will_it_fly([], 0)

    def test_flightable_empty_list(self):
        self.assertTrue(will_it_fly([], 0))

    def test_none_input_for_list(self):
        self.assertTrue(will_it_fly(None, 0))

    def test_none_input_for_weight(self):
        with self.assertRaises(TypeError):
            will_it_fly([1, 2, 3], None)

    def test_none_input_for_both(self):
        with self.assertRaises(TypeError):
            will_it_fly(None, None)

    def test_flightable_list_with_negative_numbers(self):
        self.assertTrue(will_it_fly([-1, -2, -1], 0))

    def test_flightable_list_with_zero(self):
        self.assertTrue(will_it_fly([0, 0], 1))

if __name__ == '__main__':
    unittest.main()
